function IconButton({label,children,onClick,active,disabled}: {label:string;children:ReactNode;onClick?:()=>void;active?:boolean;disabled?:boolean}) { return <button className={`icon-button ${active?'active':''}`} title={label} aria-label={label} onClick={onClick} disabled={disabled}>{children}</button>; }
function SettingsSections({sections}:{sections:{id:string;label:string;node:ReactNode}[]}) { const [active,setActive]=useState(sections[0].id); return <div className="settings-layout"><nav className="settings-nav" aria-label="Settings sections">{sections.map(x=><button type="button" key={x.id} aria-pressed={active===x.id} onClick={()=>setActive(x.id)}>{x.label}</button>)}</nav><div className="settings-pane">{sections.map(x=><section key={x.id} hidden={active!==x.id} aria-label={x.label}>{x.node}</section>)}</div></div>; }
function Modal({title,children,onClose,footer,error}: {title:string;children:ReactNode;onClose:()=>void;footer?:ReactNode;error?:string}) { const ref=useRef<HTMLDialogElement>(null); useEffect(()=>{ref.current?.showModal();},[]); return <dialog ref={ref} aria-label={title} onCancel={onClose} onClick={e=>{if(e.target===e.currentTarget)onClose();}}><div className="modal-head"><h2>{title}</h2><IconButton label="Close dialog" onClick={onClose}><X/></IconButton></div><div className="modal-body">{error&&<p className="error-text modal-error" role="alert">{error}</p>}{children}</div>{footer&&<div className="modal-foot">{footer}</div>}</dialog>; }

function inspectionEnabled(host:string,port:number|undefined,domains:string[]) { return domains.some(domain=>new RegExp('^'+domain.replace(/[.+?^${}()|[\]\\]/g,'\\$&').replace(/\*/g,'.*')+'(?::\\d+)?$').test(`${host}${port?`:${port}`:''}`)); }
function Headers({value}: {value:any}) { return <details className="headers-disclosure"><summary>Headers ({Object.keys(value??{}).length})</summary><div className="header-list">{(Array.isArray(value)?value:Object.entries(value??{})).map(([k,v]:[string,any],i:number)=><div key={i}><span>{k}</span><code>{String(v)}</code></div>)}{!Object.keys(value??{}).length&&<p className="muted">No headers</p>}</div></details>; }
function DeviceIcon({icon,color}: {icon:string;color?:string}) { const Icon=icon==='android'?Bot:icon==='ios'?Smartphone:icon==='mac'?Laptop:Globe; return <Icon style={{color}} aria-label={icon==='generic'?'Unknown platform':icon==='ios'?'iOS':icon==='mac'?'Mac':'Android'}/>; }
function ApplicationIcon({icon,name,id}: {icon?:string;name:string;id:string}) {
 const [failed,setFailed]=useState(false);
 useEffect(()=>setFailed(false),[icon]);
 if(icon&&!failed)return <img className="application-icon" src={icon} alt="" onError={()=>setFailed(true)}/>;
 const badge=appBadge(name,id);
 return <span className="app-badge" aria-hidden="true" style={{background:badge.background,color:badge.color}}>{badge.initials}</span>;
}
