  if(command==='tools-context'&&toolsMode&&payload){if(payload.section){setLabTab(payload.section);setToolsNavigation(value=>value+1);}if('recordId' in payload)setSelection(payload.recordId??null);if(payload.view)setToolsView(payload.view);return;}
